FUNCTION_BLOCK FB_QualificationFamilies EXTENDS FB_TestSuite
VAR
	_v0e : ARRAY[1..2, 1..2] OF LREAL;
	_v0a : ARRAY[1..2, 1..2] OF LREAL;
	_v1e : ARRAY[1..2, 1..2] OF REAL;
	_v1a : ARRAY[1..2, 1..2] OF REAL;
	_v2e : ARRAY[1..2, 1..2, 1..2] OF LREAL;
	_v2a : ARRAY[1..2, 1..2, 1..2] OF LREAL;
	_v3e : ARRAY[1..2, 1..2, 1..2] OF REAL;
	_v3a : ARRAY[1..2, 1..2, 1..2] OF REAL;
	_v4e : ARRAY[1..2] OF BOOL;
	_v4a : ARRAY[1..2] OF BOOL;
	_v5e : ARRAY[1..2] OF BYTE;
	_v5a : ARRAY[1..2] OF BYTE;
	_v6e : ARRAY[1..2] OF DINT;
	_v6a : ARRAY[1..2] OF DINT;
	_v7e : ARRAY[1..2] OF DWORD;
	_v7a : ARRAY[1..2] OF DWORD;
	_v8e : ARRAY[1..2] OF INT;
	_v8a : ARRAY[1..2] OF INT;
	_v9e : ARRAY[1..2] OF LINT;
	_v9a : ARRAY[1..2] OF LINT;
	_v10e : ARRAY[1..2] OF LREAL;
	_v10a : ARRAY[1..2] OF LREAL;
	_v11e : ARRAY[1..2] OF LWORD;
	_v11a : ARRAY[1..2] OF LWORD;
	_v12e : ARRAY[1..2] OF REAL;
	_v12a : ARRAY[1..2] OF REAL;
	_v13e : ARRAY[1..2] OF SINT;
	_v13a : ARRAY[1..2] OF SINT;
	_v14e : ARRAY[1..2] OF UDINT;
	_v14a : ARRAY[1..2] OF UDINT;
	_v15e : ARRAY[1..2] OF UINT;
	_v15a : ARRAY[1..2] OF UINT;
	_v16e : ARRAY[1..2] OF ULINT;
	_v16a : ARRAY[1..2] OF ULINT;
	_v17e : ARRAY[1..2] OF USINT;
	_v17a : ARRAY[1..2] OF USINT;
	_v18e : ARRAY[1..2] OF WORD;
	_v18a : ARRAY[1..2] OF WORD;
	_v19e : UINT := 1;
	_v19a : UINT := 2;
	_v20e : BOOL := TRUE;
	_v20a : BOOL := FALSE;
	_v21e : BYTE := 1;
	_v21a : BYTE := 2;
	_v22e : DATE := D#2020-01-01;
	_v22a : DATE := D#2020-01-02;
	_v23e : DATE_AND_TIME := DT#2020-01-01-00:00:00;
	_v23a : DATE_AND_TIME := DT#2020-01-02-00:00:00;
	_v24e : DINT := 1;
	_v24a : DINT := 2;
	_v25e : DWORD := 1;
	_v25a : DWORD := 2;
	_v26e : INT := 1;
	_v26a : INT := 2;
	_v27e : LINT := 1;
	_v27a : LINT := 2;
	_v28e : LREAL := 1;
	_v28a : LREAL := 2;
	_v29e : LTIME := LTIME#1ns;
	_v29a : LTIME := LTIME#2ns;
	_v30e : LWORD := 1;
	_v30a : LWORD := 2;
	_v31e : REAL := 1;
	_v31a : REAL := 2;
	_v32e : SINT := 1;
	_v32a : SINT := 2;
	_v33e : T_MaxString := 'expected';
	_v33a : T_MaxString := 'actual';
	_v34e : TIME := T#1ms;
	_v34a : TIME := T#2ms;
	_v35e : TIME_OF_DAY := TOD#01:00:00;
	_v35a : TIME_OF_DAY := TOD#02:00:00;
	_v36e : UDINT := 1;
	_v36a : UDINT := 2;
	_v37e : UINT := 1;
