	_v38e : ULINT := 1;
	_v38a : ULINT := 2;
	_v39e : USINT := 1;
	_v39a : USINT := 2;
	_v40e : WORD := 1;
	_v40a : WORD := 2;
	_v41e : WSTRING(255) := "expected";
	_v41a : WSTRING(255) := "actual";
END_VAR

PROGRAM PRG_Qualification
VAR_OUTPUT
	Done : BOOL;
	OraclePass : BOOL;
	FailedCheck : UDINT;
	SnapshotBytes : UDINT;
END_VAR
VAR
	_suite1 : FB_QualificationFamilies;
	_snapshot : REFERENCE TO ST_CoUnitRunSnapshot;

